CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS schema_versions(version int PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers(id uuid PRIMARY KEY, name text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','suspended')), demo boolean NOT NULL DEFAULT false, profile jsonb NOT NULL DEFAULT '{}');
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','owner','operator')), supplier_id uuid REFERENCES suppliers, CHECK(role='admin' OR supplier_id IS NOT NULL));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE locations(id text PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Europe/Belgrade');
INSERT INTO locations(id,name) VALUES ('prn','Prishtina International Airport'),('prishtina','Prishtina city');
CREATE TABLE vehicles(id uuid PRIMARY KEY, supplier_id uuid NOT NULL REFERENCES suppliers, name text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','published','withdrawn')), spec jsonb NOT NULL, rate jsonb NOT NULL, policy jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id uuid PRIMARY KEY, supplier_id uuid NOT NULL REFERENCES suppliers, vehicle_id uuid REFERENCES vehicles, kind text NOT NULL, expires_on date NOT NULL, state text NOT NULL DEFAULT 'quarantined' CHECK(state IN ('quarantined','approved','rejected')), object_key text NOT NULL, original_name text NOT NULL, content_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY, vehicle_id uuid NOT NULL REFERENCES vehicles, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, snapshot jsonb NOT NULL, total bigint NOT NULL CHECK(total>=0), currency text NOT NULL DEFAULT 'EUR', created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_at>start_at));
CREATE FUNCTION immutable_quote() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'quotes are immutable'; END $$;
CREATE TRIGGER immutable_quote BEFORE UPDATE OR DELETE ON quotes FOR EACH ROW EXECUTE FUNCTION immutable_quote();
CREATE TABLE bookings(id uuid PRIMARY KEY, quote_id uuid NOT NULL UNIQUE REFERENCES quotes, supplier_id uuid NOT NULL REFERENCES suppliers, vehicle_id uuid NOT NULL REFERENCES vehicles, status text NOT NULL CHECK(status IN ('awaiting_supplier','awaiting_payment','confirmed','declined','expired','cancelled','active','completed','no_show')), customer jsonb NOT NULL, access_hash text NOT NULL UNIQUE, locale text NOT NULL CHECK(locale IN ('en','sq','de')), response_due timestamptz NOT NULL, payment_due timestamptz, payment_state text NOT NULL DEFAULT 'unpaid', refund_state text NOT NULL DEFAULT 'none', dispute_state text NOT NULL DEFAULT 'none', accepted_terms text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE allocations(id uuid PRIMARY KEY, vehicle_id uuid NOT NULL REFERENCES vehicles, booking_id uuid REFERENCES bookings, period tstzrange NOT NULL, kind text NOT NULL CHECK(kind IN ('booking','hold','external','maintenance','blackout')), expires_at timestamptz, note text NOT NULL DEFAULT '', EXCLUDE USING gist (vehicle_id WITH =, period WITH &&));
CREATE INDEX allocations_booking ON allocations(booking_id);
CREATE TABLE booking_history(id bigserial PRIMARY KEY, booking_id uuid NOT NULL REFERENCES bookings, status text NOT NULL, actor text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_jobs(id uuid PRIMARY KEY, booking_id uuid NOT NULL REFERENCES bookings, status text NOT NULL, locale text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE TABLE audit_events(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity_id text NOT NULL, reason text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY, booking_id uuid NOT NULL REFERENCES bookings, provider text NOT NULL, amount bigint NOT NULL CHECK(amount>=0), state text NOT NULL, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events(event_id text PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments, state text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments, amount bigint NOT NULL, state text NOT NULL, reason text NOT NULL, UNIQUE(payment_id));
CREATE TABLE operations(id uuid PRIMARY KEY, supplier_id uuid NOT NULL REFERENCES suppliers, booking_id uuid REFERENCES bookings, kind text NOT NULL CHECK(kind IN ('pickup','return','incident','support','replacement','review','reconciliation')), state text NOT NULL DEFAULT 'open', data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commissions(booking_id uuid PRIMARY KEY REFERENCES bookings, amount bigint NOT NULL, state text NOT NULL DEFAULT 'pending');
INSERT INTO schema_versions(version) VALUES (1);
